// Pega o primeiro item recebido do trigger (formulário / webhook / etc.)
const item = $input.first();

// Descobre a chave binária da imagem (funciona com qualquer trigger:
// Form Trigger nomeia o binário com o rótulo do campo, Webhook usa "data"/"file0"...)
const chave = Object.keys(item.binary || {})[0];
if (!chave) {
  throw new Error('Nenhuma imagem recebida no fluxo. Verifique o nó de entrada.');
}

const meta = item.binary[chave];
if (!String(meta.mimeType || '').startsWith('image/')) {
  throw new Error(`O arquivo recebido não é uma imagem (mimeType: ${meta.mimeType}).`);
}

// Buffer real da imagem (funciona tanto com binário em memória quanto em filesystem)
const buffer = await this.helpers.getBinaryDataBuffer(0, chave);

// Limite de segurança: imagens muito grandes deixam a chamada lenta/pesada
const LIMITE_BYTES = 2 * 1024 * 1024; // 2 MB
if (buffer.length > LIMITE_BYTES) {
  throw new Error(`Imagem com ${(buffer.length / 1024 / 1024).toFixed(1)} MB. Use uma imagem de até 2 MB.`);
}

const pergunta =
  String(item.json['Pergunta para o modelo'] || '').trim() ||
  'Descreva esta imagem em detalhes, em português do Brasil.';

return [
  {
    json: {
      destinatario: item.json['E-mail do destinatário'],
      pergunta,
      nomeArquivo: meta.fileName || 'imagem',
      mimeType: meta.mimeType,
      tamanhoBytes: buffer.length,
      // Workers AI (LLaVA) recebe a imagem como array de bytes (uint8)
      imageBytes: Array.from(buffer),
    },
    // Renomeia o binário para "imagem" - esse nome vira o CID usado no HTML do e-mail
    binary: { imagem: meta },
  },
];

// Resposta do modelo (Workers AI) + dados/binário preparados antes da chamada HTTP
const resposta = $input.first().json;
const prep = $('Preparar imagem').first();

// LLaVA devolve result.description; Llama Vision devolve result.response
const analise =
  resposta?.result?.description ??
  resposta?.result?.response ??
  null;

if (!analise) {
  throw new Error('O modelo não retornou análise. Resposta bruta: ' + JSON.stringify(resposta));
}

// Escapa HTML para evitar injeção de conteúdo no corpo do e-mail
const esc = (s) =>
  String(s).replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));

const dataHora = new Date().toLocaleString('pt-BR', { timeZone: 'America/Sao_Paulo' });

const html = `
<div style="font-family: Arial, Helvetica, sans-serif; max-width: 640px; margin: 0 auto; color: #222;">
  <h2 style="color: #1a73e8; margin-bottom: 4px;">Análise automática de imagem</h2>
  <p style="color: #666; font-size: 13px; margin-top: 0;">Gerada pelo fluxo n8n em ${esc(dataHora)}</p>

  <h3 style="margin-bottom: 8px;">Imagem original</h3>
  <!-- "cid:imagem" = nome da propriedade binária anexada no nó Send Email -->
  <img src="cid:imagem" alt="${esc(prep.json.nomeArquivo)}"
       style="max-width: 100%; height: auto; border-radius: 8px; border: 1px solid #ddd;" />
  <p style="color: #666; font-size: 12px;">
    Arquivo: ${esc(prep.json.nomeArquivo)} (${esc(prep.json.mimeType)}, ${(prep.json.tamanhoBytes / 1024).toFixed(0)} KB)
  </p>

  <h3 style="margin-bottom: 8px;">Pergunta enviada ao modelo</h3>
  <p style="background: #f5f5f5; padding: 10px; border-radius: 6px;">${esc(prep.json.pergunta)}</p>

  <h3 style="margin-bottom: 8px;">Análise gerada pelo modelo</h3>
  <p style="white-space: pre-wrap; line-height: 1.5;">${esc(analise)}</p>

  <hr style="border: none; border-top: 1px solid #eee; margin-top: 24px;" />
  <p style="color: #999; font-size: 11px;">Modelo: Cloudflare Workers AI · Automação: n8n</p>
</div>`;

const texto = `Análise automática de imagem (${dataHora})

Imagem: ${prep.json.nomeArquivo}
Pergunta: ${prep.json.pergunta}

Análise gerada pelo modelo:
${analise}
`;

return [
  {
    json: {
      destinatario: prep.json.destinatario,
      assunto: `Análise da imagem: ${prep.json.nomeArquivo}`,
      html,
      texto,
      analise,
    },
    // Reanexa o binário da imagem para o nó de e-mail conseguir enviá-la
    binary: prep.binary,
  },
];
